package com.eurobuddha.merchinbox;

import com.eurobuddha.minimacore.i18n.Language;
import static com.eurobuddha.minimacore.i18n.R.string.*;

/** Explicit Inbox local failures only. Never use for user content, names, addresses or filenames.
 * Reuses Parlons SystemMessages' fixed lookup, literal captures and bounded diagnostic recursion.
 * Generated by adapt-pandamonium-mall-inbox-languages.py. */
public final class InboxMessages {
    private InboxMessages() {}
    public static CharSequence status(String value) {
        if (value == null) return "";
        switch(value) {
            case "ALL": return Language.msg(l10n_mall_inbox_all);
            case "PENDING": return Language.msg(l10n_utxo_pending_caps);
            case "PAID": return Language.msg(l10n_mall_shop_status_paid);
            case "CONFIRMED": return Language.msg(l10n_mall_shop_status_confirmed);
            case "SHIPPED": return Language.msg(l10n_mall_shop_status_shipped);
            case "DELIVERED": return Language.msg(l10n_mall_shop_status_delivered);
            case "UNDERPAID": return Language.msg(l10n_mall_shop_status_underpaid);
            case "WRONG_TOKEN": return Language.msg(l10n_mall_shop_status_wrong_token);
            case "INQUIRY": return Language.msg(l10n_mall_shop_enquiry);
            default: return value;
        }
    }

    public static CharSequence error(Throwable error) {
        if (error == null) return Language.msg(l10n_wallet_operation_failed);
        return message(error.getMessage() == null ? error.toString() : error.getMessage());
    }
    public static CharSequence message(String value) { return message(value,0); }
    private static CharSequence message(String value,int depth) {
        if (value == null) return "";
        if (depth >= 8) return value;
        switch(value) {
            case DeliveryCoinList.INVALID: return Language.msg(l10n_mall_inbox_coin_list_unconfirmed);
            case "transaction does not balance — refusing to sign": return Language.msg(l10n_mall_inbox_unbalanced);
            case "TOO_LONG": return Language.msg(l10n_mall_inbox_coin_list_large);
            case "buyer pay address is malformed": return Language.msg(l10n_mall_inbox_bad_address);
            case "token id is malformed": return Language.msg(l10n_mall_inbox_bad_token);
            case "bad edition index": return Language.msg(l10n_mall_inbox_bad_edition);
            case "coin list too large for this node": return Language.msg(l10n_mall_inbox_coin_list_large);
            case "no transfers could be posted": return Language.msg(l10n_mall_inbox_none_posted);
            case "this is a StateNFT collection but the order names no edition — the buyer's miniMall is outdated": return Language.msg(l10n_mall_inbox_outdated_buyer);

            case "The embedded node did not respond. Check its status in Minima Core.": return Language.msg(l10n_wallet_error_node_timeout);
            case "Node result unavailable. Outcome unknown.": return Language.msg(l10n_wallet_error_node_unknown);
            case "The embedded node is not running. No command was sent.": return Language.msg(l10n_vestr_transport_stopped);
            case "Node connection is closed.": return Language.msg(l10n_vestr_transport_closed);
            case "Too many pending node requests. Nothing was sent.": return Language.msg(l10n_vestr_transport_busy);
            case "Node result was not received. Outcome remains unknown.": return Language.msg(l10n_vestr_transport_not_received);
            case "Node request could not complete. Outcome remains unknown.": return Language.msg(l10n_vestr_transport_request_failed);
            case "Node result is unavailable. Outcome remains unknown.": return Language.msg(l10n_vestr_transport_result_unavailable);
            case "Node request cancelled before execution. Nothing was sent.": return Language.msg(l10n_vestr_transport_cancelled);
            case "Invalid node result. Outcome remains unknown.": return Language.msg(l10n_vestr_transport_invalid);
            case "NOT_ENABLED": return Language.msg(l10n_mall_shop_node_unavailable);
            case "Node connection closed.": return Language.msg(l10n_vestr_transport_closed);
            case "box seed keypair failed": return Language.msg(l10n_mall_shop_box_key_failed);
            case "sign seed keypair failed": return Language.msg(l10n_mall_shop_sign_key_failed);
            case "HKDF failed": return Language.msg(l10n_mall_shop_hkdf_failed);
            case "the node rejected the send": return Language.msg(l10n_mail_rejected_send);
            case "sign failed": return Language.msg(l10n_mail_sign_failed);
            case "seal failed": return Language.msg(l10n_mail_seal_failed);
            case "Invalid payment address, token or amount.": return Language.msg(l10n_mall_shop_invalid_payment);
            default: break;
        }
        java.util.regex.Matcher command = java.util.regex.Pattern.compile("(txndelete|txncreate|txninput|txnoutput|txnstate|txnbasics|txncheck|txnsign|txnpost) failed(?: : ((?s:.*)))?").matcher(value);
        if (command.matches()) return command.group(2) == null ? Language.msg(l10n_casino_command_failed, command.group(1)) : Language.msg(l10n_casino_command_failed_detail, command.group(1), message(command.group(2), depth + 1));
        java.util.regex.Matcher piece = java.util.regex.Pattern.compile("piece #([0-9]+) of ((?s:.*)) is not in this wallet — sold or moved\\?").matcher(value);
        if (piece.matches()) return Language.msg(l10n_mall_inbox_missing_piece, piece.group(1), piece.group(2));
        java.util.regex.Matcher state = java.util.regex.Pattern.compile("piece #([0-9]+) carries state this app won't replay").matcher(value);
        if (state.matches()) return Language.msg(l10n_mall_inbox_unsafe_state, state.group(1));
        java.util.regex.Matcher collection = java.util.regex.Pattern.compile("no pieces of ((?s:.*)) are in this wallet — sold or moved\\?").matcher(value);
        if (collection.matches()) return Language.msg(l10n_mall_inbox_missing_collection, collection.group(1));
        for(int i=0;i<PATTERNS.length;i++) {
            java.util.regex.Matcher match=PATTERNS[i].matcher(value);
            if(!match.matches())continue;
            Object[] arguments=new Object[match.groupCount()];
            for(int j=0;j<arguments.length;j++) {
                String literal=match.group(j+1);
                arguments[j]=DIAGNOSTIC[i][j] ? message(literal,depth+1) : literal;
            }
            return Language.msg(RESOURCES[i],arguments);
        }
        return value;
    }
    private static final java.util.regex.Pattern[] PATTERNS={
        java.util.regex.Pattern.compile("encrypt\\ failed:\\ ((?s:.*))"),
        java.util.regex.Pattern.compile("seal\\ error:\\ ((?s:.*))")
    };
    private static final int[] RESOURCES={l10n_mail_encrypt_failed,l10n_mail_seal_error};
    private static final boolean[][] DIAGNOSTIC={{true},{true}};
}
